            float potential = 1.0 / (0.05 + abs(d_blur));

            // Accumulate density, scaled by integration step and Torque (uSpiral)
            density += potential * 0.05 * uSpiral; 

            if(d < 0.001 || t > 10.0) break;
            t += d;
        }

        vec3 color = vec3(0.0);

        if(t < 10.0) {
            // Surface Geometry (The Matter)
            vec3 p = ro + rd * t;

            // Calculate Normal (Must use current time for sharp edges)
            vec2 e = vec2(0.005, 0.0);
            vec3 n = normalize(vec3(
                map(p + e.xyy, uTime) - map(p - e.xyy, uTime),
                map(p + e.yxy, uTime) - map(p - e.yxy, uTime),
                map(p + e.yyx, uTime) - map(p - e.yyx, uTime)
            ));

            // Standard Blinn-Phong Lighting
            vec3 light = normalize(vec3(0.5, 1.0, -1.0));
            float diff = max(dot(n, light), 0.0);
            float spec = pow(max(dot(reflect(-light, n), -rd), 0.0), 16.0);

            color = vec3(0.1, 0.4, 0.8) * diff + spec;
        } 

        // VOLUMETRIC COMPOSITING
        // Map accumulated density to spectral color (Phase Shift)
        vec3 fieldColor = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + density * 0.2);

        // Add volumetric field to the surface color (Additive Blending)
        color += fieldColor * density * 0.02;

        gl_FragColor = vec4(color, 1.0);
    }
`;

export const VERTEX_SHADER_SOURCE = `
    attribute vec2 position;
    void main() {
        gl_Position = vec4(position, 0.0, 1.0);
    }
`;

export const FRAGMENT_SHADER_SOURCE = `
    precision highp float;
    uniform vec2 uResolution;
    uniform float uTime;
    uniform float uMu;    // The 4D constant (Shape shifter)
    uniform float uIter;  // Fractal Iterations
    uniform float uRot;   // 4D Rotation
    uniform float uZoom;  // Scale
    uniform float uSpiral; // Torque (Time Spiral)

    // --- QUATERNION MATH LIBRARY ---
    vec4 qMul(vec4 a, vec4 b) {
        return vec4(
            a.x * b.x - a.y * b.y - a.z * b.z - a.w * b.w,
            a.x * b.y + a.y * b.x + a.z * b.w - a.w * b.z,
            a.x * b.z - a.y * b.w + a.z * b.x + a.w * b.y,
            a.x * b.w + a.y * b.z - a.z * b.y + a.w * b.x
        );
    }

    vec4 qSq(vec4 a) {
        return vec4(
            a.x * a.x - a.y * a.y - a.z * a.z - a.w * a.w,
            2.0 * a.x * a.y,
            2.0 * a.z * a.x,
            2.0 * a.w * a.x
        );
    }

    mat2 rot(float a) {
        float s = sin(a), c = cos(a);
        return mat2(c, -s, s, c);
    }

    // "Spiral Time" Logic
    vec4 getSpiralState(float time, float tempo) {
        float cycle = sin(time * tempo);
        float evolution = time * 0.1; 
        float spiralX = cos(evolution) * cycle;
        float spiralY = sin(evolution) * cycle;
        return vec4(spiralX, spiralY, evolution, 0.0);
    }

    // --- THE 4D FRACTAL FIELD ---
    // Now accepts 'currentZoom' to simulate Refractive Index per wavelength
    float map(vec3 p, float timeInput, float currentZoom) {
        p /= currentZoom; 

        vec4 z = vec4(p, 0.0);

        // Apply SLIP rotation
        float t = timeInput * 0.2 + uRot;
        z.xw *= rot(t * 0.5);
        z.yz *= rot(t * 0.8);

        // Apply Spiral Torque
        vec4 spiral = getSpiralState(timeInput, 2.0);
        vec4 c = vec4(uMu, 0.6, -0.4, -0.2) + (spiral * uSpiral); 

        float dr = 1.0; 
        float r = 0.0;  

        for(int i = 0; i < 10; i++) {
            if(float(i) > uIter) break;
            r = length(z);
            if(r > 4.0) break;
            dr = 2.0 * r * dr;
            z = qSq(z) + c;
        }

        return 0.25 * log(r) * r / dr * currentZoom;
    }

    // --- REUSABLE RENDER PASS (SPECTRAL RAYMARCHING) ---
    // Calculates the scene color for a specific refractive index (Zoom)
    vec3 renderPass(vec3 ro, vec3 rd, float currentZoom) {
        float t = 0.0;
        float d = 0.0;
        float density = 0.0; 
        float dt = 0.04; // Time delta for motion blur

        // Raymarch Loop (Optimized iterations for performance)
        for(int i = 0; i < 64; i++) {
            vec3 p = ro + rd * t;

            // Multi-Tap Sampling (Temporal Persistence)
            d = map(p, uTime, currentZoom); 
            float d_past = map(p, uTime - dt, currentZoom);
            float d_blur = min(d, d_past); // Motion Blur Smear

            // Volumetric Density (Inverse Square Law)
            float potential = 1.0 / (0.05 + abs(d_blur));
            density += potential * 0.05 * uSpiral; 

            if(d < 0.001 || t > 10.0) break;
            t += d;
        }

        vec3 color = vec3(0.0);

        if(t < 10.0) {
            // Surface Geometry
            vec3 p = ro + rd * t;
            vec2 e = vec2(0.005, 0.0);

            // Calculate Normals using the specific Zoom context
            vec3 n = normalize(vec3(
                map(p + e.xyy, uTime, currentZoom) - map(p - e.xyy, uTime, currentZoom),
                map(p + e.yxy, uTime, currentZoom) - map(p - e.yxy, uTime, currentZoom),
                map(p + e.yyx, uTime, currentZoom) - map(p - e.yyx, uTime, currentZoom)
            ));

            vec3 light = normalize(vec3(0.5, 1.0, -1.0));
            float diff = max(dot(n, light), 0.0);
            float spec = pow(max(dot(reflect(-light, n), -rd), 0.0), 16.0);

            color = vec3(0.1, 0.4, 0.8) * diff + spec;
        } 

        // Volumetric Glow
        vec3 fieldColor = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + density * 0.2);
        color += fieldColor * density * 0.02;

        return color;
    }

    // --- MAIN RENDER LOOP (FARADAY ROTATION) ---
    void main() {
        vec2 uv = (gl_FragCoord.xy - 0.5 * uResolution.xy) / uResolution.y;
        vec3 ro = vec3(0.0, 0.0, 2.5);
        vec3 rd = normalize(vec3(uv, -1.0));

        // Calculate Dispersion Strength from Magnetic Torque
        // High uSpiral = High Dispersion (Stronger Field)
        float dispersion = uSpiral * 0.025;

        // --- SPECTRAL SPLIT ---
        // We fire 3 rays with slightly different refractive indices (Zoom levels)

        // RED CHANNEL (Low Interaction)
        float zoomR = uZoom;
        vec3 colR = renderPass(ro, rd, zoomR);

        // GREEN CHANNEL (Medium Interaction)
        float zoomG = uZoom * (1.0 + dispersion);
        vec3 colG = renderPass(ro, rd, zoomG);

        // BLUE CHANNEL (High Interaction)
        float zoomB = uZoom * (1.0 + dispersion * 2.0);
        vec3 colB = renderPass(ro, rd, zoomB);

        // Composite the spectral channels
        // We only take the R component from the Red pass, G from Green, etc.
        gl_FragColor = vec4(colR.r, colG.g, colB.b, 1.0);
    }
`;
